package br.com.folha.notes;
import java.util.*;
public final class JapaneseTest {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args){List<Ink.Stroke> raw=new ArrayList<>();Ink.Stroke horizontal=new Ink.Stroke(0xff263c32,2,false);horizontal.points.add(new Ink.Point(10,20,.2f));horizontal.points.add(new Ink.Point(30,21,1));horizontal.points.add(new Ink.Point(50,23,.6f));raw.add(horizontal);List<Ink.Stroke> adjusted=JapaneseGeometry.adjust(raw,null);check(adjusted.get(0)!=horizontal&&horizontal.points.get(0).y==20,"Original is immutable");check(adjusted.get(0).points.get(0).y==adjusted.get(0).points.get(2).y,"Near-horizontal line is aligned");check(adjusted.get(0).points.get(0).pressure==horizontal.points.get(0).pressure,"Pressure retained");check(adjusted.get(0).id.equals(horizontal.id),"Stable stroke identity");Ink.Stroke curve=new Ink.Stroke(0xff263c32,2,false);curve.points.add(new Ink.Point(20,20,.3f));curve.points.add(new Ink.Point(35,45,.7f));curve.points.add(new Ink.Point(20,70,1));List<Ink.Stroke> curved=JapaneseGeometry.adjust(Collections.singletonList(curve),null);check(curved.get(0).points.get(1).x>curved.get(0).points.get(0).x+8,"Curves do not become straight");Ink.Stroke hook=new Ink.Stroke(0xff263c32,2,false);hook.points.add(new Ink.Point(30,10,.5f));hook.points.add(new Ink.Point(30,85,1));hook.points.add(new Ink.Point(24,91,.7f));List<Ink.Stroke> hooked=JapaneseGeometry.adjust(Collections.singletonList(hook),null);check(Math.abs(hooked.get(0).points.get(1).x-hooked.get(0).points.get(2).x)>3,"Terminal hooks are preserved");for(String type:new String[]{"kanji","kana","genko200","genko400"}){boolean found=false;for(float x=0;x<Paper.width(type);x+=3)for(float y=0;y<Paper.height(type);y+=4){float[] cell=JapaneseGeometry.cell(type,Paper.width(type),Paper.height(type),x,y);if(cell!=null){check(x>=cell[0]&&x<=cell[2]&&y>=cell[1]&&y<=cell[3],"Cell bounds");found=true;}}check(found,"Template cell lookup");}check(JapaneseGeometry.japanese("水")&&JapaneseGeometry.japanese("あ")&&JapaneseGeometry.japanese("カ")&&!JapaneseGeometry.japanese("mizu")&&!JapaneseGeometry.japanese("水木"),"Single Japanese character filter");Ink.Stroke glyph=new Ink.Stroke(0xff263c32,1,false);glyph.glyph="0,0 1000,0 1000,1000 0,1000";glyph.text="水";glyph.x=10;glyph.y=20;glyph.boxW=30;glyph.boxH=40;check(GlyphData.contours(glyph.glyph).size()==1,"Contour parsing");check(glyph.copy(false).glyph.equals(glyph.glyph),"Copy retains vector contours");check(Arrays.equals(glyph.bounds(),new float[]{10,20,40,60}),"Regular object bounds");check(glyph.hit(20,30,0)&&!glyph.hit(100,100,0),"Glyph hit test");check(glyph.transform(0,0,5,6,2,false).boxW==60,"Glyph transforms");check(Ink.cut(glyph,15,25,20,30,1).isEmpty(),"Eraser removes regular character atomically");check(Ink.cut(glyph,100,100,110,110,1).get(0)==glyph,"Distant eraser preserves glyph");boolean rejected=false;try{GlyphData.contours("0,0 1001,0 0,20");}catch(IllegalArgumentException e){rejected=true;}check(rejected,"Invalid contour rejected");System.out.println("Japanese cleanup, pressure, curves, grid mapping, character filter, contour validation and glyph editing passed.");}
}
